import {
  createDraftSnapshotFn,
  deleteEndedDraftFn,
  listDraftsFn,
  restoreEndedDraftFn,
  createSnapshotFn,
  deleteSnapshotFn,
  listDraftSnapshotsFn,
  listSnapshotsFn,
  restoreDraftSnapshotFn,
  restoreSnapshotFn,
} from '#/server/projects.functions'
import type { DraftRecord, DraftState, DraftSummary, SnapshotKind, SnapshotSummary } from '#/server/projects.server'
import { useConfirm } from './ConfirmDialog'
import { ReadOnlyProvider } from './readOnly'
