export const formatTime = (iso: string) => new Date(iso).toLocaleString('sk-SK', { dateStyle: 'medium', timeStyle: 'short' })

const KIND: Record<SnapshotKind, { text: string; className: string }> = {
  named: { text: 'Pomenovaná', className: 'bg-indigo-500/15 text-indigo-200' },
  auto: { text: 'Automatická záloha', className: 'bg-white/5 text-zinc-300' },
  safety: { text: 'Pred obnovením/importom', className: 'bg-amber-500/10 text-amber-200' },
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Agents create, edit and discard drafts"
  // Changes: Final snapshot of an ended draft (shown once draft histories get their tabs).
  final: { text: 'Konečný stav návrhu', className: 'bg-emerald-500/10 text-emerald-200' },
}

/** Server-side limit for a version label (LABEL_MAX in projects.server). */
const LABEL_MAX = 200

/**
 * One history shown as a tab of the History page: the project's or a draft's. Operations a source lacks are not
 * offered (e.g. an ended draft's history – #11 – would have only `list`).
 */
interface HistorySource {
  /** Stable tab key: 'project' or the draft id. */
  key: string
  kind: 'project' | 'draft'
  /** Tab text (the draft label for a draft). */
  label: string
  list: () => Promise<SnapshotSummary[]>
  /** Saves local edits first where relevant; rejects with a Slovak message when it cannot. */
  save?: (label: string) => Promise<unknown>
  /** Restores into the source (a safety snapshot of the current state is taken first); rejects like save. */
  restore?: (snapshotId: number) => Promise<void>
  remove?: (snapshotId: number) => Promise<unknown>
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Ended drafts in history"
  // Changes: An ended draft's source: how it ended, restore into a new draft, delete the whole history.
  ended?: { state: Exclude<DraftState, 'open'>; at: string }
  /** Restores a version into a new open draft (ended drafts) and returns it. */
  restoreAsNew?: (snapshotId: number) => Promise<DraftRecord>
  /** Deletes the source with its whole history (ended drafts). */
  removeAll?: () => Promise<void>
}

const ENDED: Record<Exclude<DraftState, 'open'>, { badge: string; sentence: string; className: string }> = {
  adopted: { badge: 'Prevzatý', sentence: 'bol prevzatý do projektu', className: 'border-emerald-300/50 text-emerald-200' },
  discarded: { badge: 'Zahodený', sentence: 'bol zahodený', className: 'border-zinc-400/50 text-zinc-300' },
}

const formatDate = (iso: string) => new Date(iso).toLocaleDateString('sk-SK', { dateStyle: 'medium' })

export function HistoryTab({
  projectId,
  drafts,
  currentDraftId,
  onSaveSnapshot,
  onRestore,
  onOpenDraft,
}: {
  projectId: string
  /** The project's open drafts – one tab each. */
  drafts: DraftSummary[]
  /** The draft shown in this editor (null = the project); its tab is selected first and uses the session. */
  currentDraftId: string | null
  /** The session's named version (of the project or of the open draft). */
  onSaveSnapshot: (label: string) => Promise<unknown>
  /** The session's restore (refreshes the open view). */
  onRestore: (snapshotId: number) => Promise<void>
  /** Opens a draft in the editor (after restoring an ended draft's version into a new one). */
  onOpenDraft: (draftId: string) => void
}) {
  const listProject = useServerFn(listSnapshotsFn)
  const listDraft = useServerFn(listDraftSnapshotsFn)
  const saveProject = useServerFn(createSnapshotFn)
  const restoreProject = useServerFn(restoreSnapshotFn)
  const removeProject = useServerFn(deleteSnapshotFn)
  const saveDraft = useServerFn(createDraftSnapshotFn)
  const restoreDraft = useServerFn(restoreDraftSnapshotFn)
  const listDrafts = useServerFn(listDraftsFn)
  const restoreEnded = useServerFn(restoreEndedDraftFn)
  const deleteEnded = useServerFn(deleteEndedDraftFn)

  // Ended drafts are loaded here (fresh each time the page opens, so a draft an agent ended meanwhile shows too).
  const [endedDrafts, setEndedDrafts] = useState<DraftSummary[]>([])
  useEffect(() => {
    let live = true
    listDrafts({ data: { id: projectId } }).then(
      (all) => live && setEndedDrafts(all.filter((d) => d.state !== 'open')),
      () => {},
    )
    return () => {
      live = false
    }
  }, [projectId, listDrafts])

  const sources = useMemo((): HistorySource[] => {
    const project: HistorySource = {
      key: 'project',
      kind: 'project',
      label: 'Projekt',
      list: () => listProject({ data: { id: projectId } }),
      save:
        currentDraftId === null
          ? onSaveSnapshot
          : async (label) => {
              if (!(await saveProject({ data: { id: projectId, label } }))) throw new Error('Projekt už neexistuje')
            },
      restore:
        currentDraftId === null
          ? onRestore
          : async (snapshotId) => {
              if (!(await restoreProject({ data: { id: projectId, snapshotId } }))) throw new Error('Verzia už neexistuje')
            },
      remove: (snapshotId) => removeProject({ data: { id: projectId, snapshotId } }),
    }
    const endedIds = new Set(endedDrafts.map((d) => d.id))
    const draftSources = drafts.filter((d) => !endedIds.has(d.id)).map((d): HistorySource => {
      const current = d.id === currentDraftId
      return {
        key: d.id,
        kind: 'draft',
        label: d.label,
        list: () => listDraft({ data: { draftId: d.id } }),
        save: current
          ? onSaveSnapshot
          : async (label) => {
              if (!(await saveDraft({ data: { draftId: d.id, label } }))) throw new Error('Návrh už neexistuje')
            },
        restore: current
          ? onRestore
          : async (snapshotId) => {
              if (!(await restoreDraft({ data: { draftId: d.id, snapshotId } }))) throw new Error('Verzia už neexistuje')
            },
      }
    })
    const endedSources = endedDrafts.map(
      (d): HistorySource => ({
        key: d.id,
        kind: 'draft',
        label: d.label,
        list: () => listDraft({ data: { draftId: d.id } }),
        ended: { state: d.state as Exclude<DraftState, 'open'>, at: d.endedAt ?? d.updatedAt },
        restoreAsNew: async (snapshotId) => {
          const draft = await restoreEnded({ data: { draftId: d.id, snapshotId } })
          if (!draft) throw new Error('Verzia už neexistuje')
          return draft
        },
        removeAll: async () => {
          await deleteEnded({ data: { draftId: d.id } })
          setEndedDrafts((list) => list.filter((e) => e.id !== d.id))
        },
      }),
    )
    return [project, ...draftSources, ...endedSources]
  }, [
    projectId,
    drafts,
    endedDrafts,
    currentDraftId,
    onSaveSnapshot,
    onRestore,
    listProject,
    listDraft,
    saveProject,
    restoreProject,
    removeProject,
    saveDraft,
    restoreDraft,
    restoreEnded,
    deleteEnded,
  ])

  const [selectedKey, setSelectedKey] = useState(currentDraftId ?? 'project')
  const selected = sources.find((s) => s.key === selectedKey) ?? sources[0]
  const baseId = useId()
  const tabId = (key: string) => `${baseId}-tab-${key}`
  const tabRefs = useRef(new Map<string, HTMLButtonElement>())
  // After an ended draft's history is deleted, its tab is gone: select and focus the project tab.
  const onRemoved = () => {
    setSelectedKey('project')
    requestAnimationFrame(() => tabRefs.current.get('project')?.focus())
  }

  // Selection by activation (Enter/Space/click): selecting loads that history, so arrows only move focus.
  const onTabKey = (e: KeyboardEvent, index: number) => {
    const target = tabKeyTarget(e.key, index, sources.length)
    if (target === null) return
    e.preventDefault()
    tabRefs.current.get(sources[target].key)?.focus()
  }
  useEffect(() => {
    tabRefs.current.get(selected.key)?.scrollIntoView({ block: 'nearest', inline: 'nearest', container: 'nearest' } as ScrollIntoViewOptions)
  }, [selected.key])

  return (
    <div>
      <div role="tablist" aria-label="História" className="history-tabs mb-4 flex gap-1 overflow-x-auto border-b border-white/10">
        {sources.map((s, i) => {
          const isSelected = s.key === selected.key
          return (
            <button
              key={s.key}
              ref={(el) => {
                if (el) tabRefs.current.set(s.key, el)
                else tabRefs.current.delete(s.key)
              }}
              type="button"
              role="tab"
              id={tabId(s.key)}
              aria-selected={isSelected}
              tabIndex={isSelected ? 0 : -1}
              onClick={() => setSelectedKey(s.key)}
              onKeyDown={(e) => onTabKey(e, i)}
              className="history-tab flex max-w-[20rem] flex-none items-center gap-2 rounded-t-lg px-3 py-2 text-sm"
            >
              {s.ended ? (
                <span
                  className={cx(
                    'flex-none rounded-full border px-1.5 text-[10px] font-semibold tracking-wide uppercase',
                    ENDED[s.ended.state].className,
                  )}
                >
                  {ENDED[s.ended.state].badge}
                  <span className="sr-only"> návrh:</span>
                </span>
              ) : s.kind === 'draft' && (
                <span className="flex-none rounded-full border border-amber-300/50 px-1.5 text-[10px] font-semibold tracking-wide text-amber-200 uppercase">
                  Návrh<span className="sr-only">:</span>
                </span>
              )}
              <span className="truncate" title={s.label}>
                {s.label}
              </span>
              {s.ended && (
                <time dateTime={s.ended.at} className="flex-none text-xs text-zinc-400">
                  <span className="sr-only">, </span>
                  {formatDate(s.ended.at)}
                </time>
              )}
            </button>
          )
        })}
      </div>
      {sources.map((s) => (
        <div key={s.key} role="tabpanel" aria-labelledby={tabId(s.key)} hidden={s.key !== selected.key}>
          {s.key === selected.key && <SnapshotHistory source={s} onOpenDraft={onOpenDraft} onRemoved={onRemoved} />}
        </div>
      ))}
    </div>
  )
}

function SnapshotHistory({
  source,
  onOpenDraft,
  onRemoved,
}: {
  source: HistorySource
  onOpenDraft: (draftId: string) => void
  onRemoved: () => void
}) {
  const toast = useToast()
  const confirm = useConfirm()
  const [snapshots, setSnapshots] = useState<SnapshotSummary[] | null>(null)
  const [label, setLabel] = useState('')
  const [busy, setBusy] = useState(false)
  const headingRef = useRef<HTMLSpanElement>(null)
  const helpId = useId()
  const itemRefs = useRef(new Map<number, HTMLButtonElement>())
  // After restore/delete (buttons were disabled while busy): the version whose first button gets focus (null = heading).
  const focusAfter = useRef<number | null | undefined>(undefined)
  const isDraft = source.kind === 'draft'
  const { list } = source

  const reload = useCallback(async () => setSnapshots(await list()), [list])
  useEffect(() => {
    void reload()
  }, [reload])

  useLayoutEffect(() => {
    // Wait until the buttons are enabled again (they are disabled while busy).
    const target = focusAfter.current
    if (target === undefined || busy) return
    focusAfter.current = undefined
    ;((target !== null && itemRefs.current.get(target)) || headingRef.current)?.focus()
  }, [snapshots, busy])

  const run = async (fn: () => Promise<void>, failTitle: string) => {
    setBusy(true)
    try {
      await fn()
    } catch (err) {
      toast({ title: failTitle, description: err instanceof Error ? err.message : String(err), tone: 'bad' })
    } finally {
      setBusy(false)
    }
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
  // Changes: No "Verzia uložená" unless local edits were saved first (the session rejects otherwise → error toast).
  const save = (e: FormEvent) => {
    e.preventDefault()
    if (busy || !source.save) return
    const saveSnapshot = source.save
    void run(async () => {
      await saveSnapshot(label.trim() || `Verzia ${new Date().toLocaleString('sk-SK')}`)
      setLabel('')
      await reload()
      toast({ title: 'Verzia uložená', tone: 'ok' })
    }, 'Verziu sa nepodarilo uložiť')
  }

  const restore = async (s: SnapshotSummary) => {
    if (!source.restore) return
    const restoreSnapshot = source.restore
    const ok = await confirm({
      title: isDraft ? 'Obnoviť verziu návrhu?' : 'Obnoviť verziu?',
      body: isDraft ? (
        <>
          Do návrhu „{source.label}“ sa obnoví verzia „{s.label}“ ({formatTime(s.createdAt)}). Aktuálny stav návrhu sa najprv uloží do
          jeho histórie. Projekt sa nezmení.
        </>
      ) : (
        <>
          Obnoví sa verzia „{s.label}“ ({formatTime(s.createdAt)}). Aktuálny stav sa najprv uloží do histórie.
        </>
      ),
      confirmLabel: 'Obnoviť',
    })
    if (!ok) return
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
    // Changes: Restore through the session – refuses while local edits are unsaved or in conflict.
    await run(async () => {
      await restoreSnapshot(s.id)
      focusAfter.current = s.id
      await reload()
      toast({ title: 'Verzia obnovená', description: s.label, tone: 'ok' })
    }, 'Obnovenie zlyhalo')
  }

  const del = async (s: SnapshotSummary, index: number) => {
    if (!source.remove) return
    const remove = source.remove
    const ok = await confirm({
      title: 'Zmazať verziu?',
      body: <>Verzia „{s.label}“ ({formatTime(s.createdAt)}) sa natrvalo odstráni.</>,
      confirmLabel: 'Zmazať',
      tone: 'danger',
    })
    if (!ok || !snapshots) return
    const neighbour = snapshots[index + 1] ?? snapshots[index - 1]
    await run(async () => {
      await remove(s.id)
      focusAfter.current = neighbour ? neighbour.id : null
      await reload()
    }, 'Mazanie zlyhalo')
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Ended drafts in history"
  // Changes: Restore from an ended draft = a new draft forked from the project's current state, opened right away.
  const restoreAsNew = async (s: SnapshotSummary) => {
    if (!source.restoreAsNew) return
    const restoreIntoDraft = source.restoreAsNew
    const ok = await confirm({
      title: 'Obnoviť do nového návrhu?',
      body: (
        <>
          Vznikne nový návrh „{source.label} (obnovený)“ z aktuálneho stavu projektu, s časťami z verzie „{s.label}“ (
          {formatTime(s.createdAt)}), a otvorí sa. Ukončený návrh ani projekt sa nezmenia.
        </>
      ),
      confirmLabel: 'Vytvoriť návrh',
    })
    if (!ok) return
    await run(async () => {
      const draft = await restoreIntoDraft(s.id)
      toast({ title: 'Nový návrh vytvorený', description: draft.label, tone: 'ok' })
      onOpenDraft(draft.id)
    }, 'Obnovenie zlyhalo')
  }

  const removeAll = async () => {
    if (!source.removeAll) return
    const remove = source.removeAll
    const ok = await confirm({
      title: `Zmazať históriu návrhu „${source.label}“?`,
      body: <>Ukončený návrh a všetky jeho verzie sa natrvalo odstránia. Projekt ani jeho história sa nezmenia.</>,
      confirmLabel: 'Zmazať históriu',
      tone: 'danger',
    })
    if (!ok) return
    await run(async () => {
      await remove()
      toast({ title: 'História návrhu zmazaná', description: source.label, tone: 'ok' })
      onRemoved()
    }, 'Mazanie zlyhalo')
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Make the two sections left and right resizable"
  // Changes: Resizable two-column layout.
  // A read-only content view (a draft, for now) still has a working history: its fields are not content fields.
  return (
    <ReadOnlyProvider value={false}>
    <SplitLayout>
      {source.save ? (
        <Panel title={isDraft ? 'Uložiť verziu návrhu' : 'Uložiť verziu'}>
          <form onSubmit={save}>
            <TextInput
              value={label}
              placeholder="napr. Pred zmenou výrazov"
              onChange={(e) => setLabel(e.target.value)}
              maxLength={LABEL_MAX}
              enterKeyHint="done"
              aria-label={isDraft ? 'Popis verzie návrhu' : 'Popis verzie'}
              aria-describedby={helpId}
            />
            <div className="mt-3">
              <PrimaryButton type="submit" disabled={busy}>
                Uložiť verziu
              </PrimaryButton>
            </div>
          </form>
          <Help>
            <span id={helpId}>
              {isDraft
                ? 'Návrh má vlastnú históriu. Pri jeho úpravách sa najviac raz za 20 minút uloží automatická záloha (posledných 30). ' +
                  'Pred obnovením sa aktuálny stav návrhu vždy odloží sem (posledných 10). Projekt sa tým nemení.'
                : 'Pri úpravách sa najviac raz za 20 minút uloží aj automatická záloha (posledných 30). Pred obnovením alebo importom ' +
                  'sa aktuálny stav vždy odloží sem.'}
            </span>
          </Help>
        </Panel>
      ) : source.ended ? (
        <Panel title="Ukončený návrh">
          <p className="text-sm text-zinc-300">
            Návrh „{source.label}“ {ENDED[source.ended.state].sentence}{' '}
            <time dateTime={source.ended.at}>{formatTime(source.ended.at)}</time>.
          </p>
          <Help>
            Jeho verzie sa dajú len prezerať. Obnovením verzie vznikne nový návrh z aktuálneho stavu projektu s časťami z tejto
            verzie.
          </Help>
          <div className="mt-3">
            <DangerButton disabled={busy} onClick={() => void removeAll()}>
              Zmazať históriu návrhu…
            </DangerButton>
          </div>
        </Panel>
      ) : (
        <Panel title="História návrhu">
          <Help>Verzie sa dajú len prezerať.</Help>
        </Panel>
      )}

      <Panel
        title={
          <span ref={headingRef} tabIndex={-1} className="rounded focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-400">
            {isDraft ? `História návrhu „${source.label}“` : 'História projektu'}
          </span>
        }
      >
        {snapshots === null ? (
          <div className="text-sm text-zinc-400">Načítavam…</div>
        ) : snapshots.length === 0 ? (
          <div className="text-sm text-zinc-400">Zatiaľ žiadne uložené verzie.</div>
        ) : (
          <ul className="divide-y divide-white/5">
            {snapshots.map((s, i) => {
              const labelId = `snapshot-${s.id}-label`
              const kind = KIND[s.kind]
              return (
                <li key={s.id} className="flex flex-wrap items-center gap-3 py-2.5">
                  <div className="min-w-0 flex-1">
                    {/* Full label, wrapped (no truncation that would hide part of it). */}
                    <div id={labelId} className="text-sm text-zinc-200 [overflow-wrap:anywhere]">
                      {s.label}
                    </div>
                    <div className="mt-0.5 flex flex-wrap items-center gap-2 text-xs text-zinc-400">
                      {formatTime(s.createdAt)}
                      <span className={cx('rounded-full px-2 py-0.5 text-[11px]', kind.className)}>{kind.text}</span>
                    </div>
                  </div>
                  {source.restore && (
                    <Button
                      ref={(el) => {
                        if (el) itemRefs.current.set(s.id, el)
                        else itemRefs.current.delete(s.id)
                      }}
                      disabled={busy}
                      aria-describedby={labelId}
                      onClick={() => void restore(s)}
                    >
                      Obnoviť
                    </Button>
                  )}
                  {source.restoreAsNew && (
                    <Button
                      ref={(el) => {
                        if (el) itemRefs.current.set(s.id, el)
                        else itemRefs.current.delete(s.id)
                      }}
                      disabled={busy}
                      aria-describedby={labelId}
                      onClick={() => void restoreAsNew(s)}
                    >
                      Obnoviť do nového návrhu
                    </Button>
                  )}
                  {source.remove && (
                    <DangerButton disabled={busy} aria-describedby={labelId} onClick={() => void del(s, i)}>
                      Zmazať
                    </DangerButton>
                  )}
                </li>
              )
            })}
          </ul>
        )}
      </Panel>
    </SplitLayout>
    </ReadOnlyProvider>
  )
}
